result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test/castle.test.js", "content": "import { describe, it, expect } from 'vitest';
import { generateCastle, isGrounded, castleMesh } from '../src/castle.js';

describe('generateCastle / isGrounded', () => {
  it('is grounded for generated castles across seeds 1-10', () => {
    for (let seed = 1; seed <= 10; seed++) {
      const voxels = generateCastle(seed);
      expect(isGrounded(voxels), `seed ${seed} should be grounded`).toBe(true);
    }
  });

  it('deleting a mid-tower voxel breaks grounding', () => {
    const voxels = generateCastle(1);
    // A mid-tower voxel: corner tower column at (0, 2, 0)
    const midTowerKey = '0,2,0';
    expect(voxels.has(midTowerKey)).toBe(true);

    const copy = new Set(voxels);
    copy.delete(midTowerKey);
    expect(isGrounded(copy)).toBe(false);
  });

  it('instance count equals voxel set size', () => {
    for (const seed of [1, 7, 42]) {
      const voxels = generateCastle(seed);
      const mesh = castleMesh(voxels);
      expect(mesh.count).toBe(voxels.size);
    }
  });

  it('same seed gives identical voxel set; seeds 1 and 2 differ', () => {
    const a1 = generateCastle(1);
    const a2 = generateCastle(1);
    expect(a1).toEqual(a2);

    const b = generateCastle(2);
    expect(a1).not.toEqual(b);
  });

  it('no voxel has y < 0', () => {
    for (let seed = 1; seed <= 10; seed++) {
      const voxels = generateCastle(seed);
      for (const k of voxels) {
        const y = Number(k.split(',')[1]);
        expect(y, `seed ${seed}, voxel ${k}`).toBeGreaterThanOrEqual(0);
      }
    }
  });
});
"})
